import * as T from './three.module.js';
export function createFarmPet(type,variant=0){const root=new T.Group(),legs=[],tail=new T.Group(),head=new T.Group(),fur=new T.MeshStandardMaterial({color:(type==='dog'?['#a37e58','#d0bb98','#665d51']:['#bd9971','#727b7b','#d5cbb9'])[variant%3],roughness:.95}),dark=new T.MeshStandardMaterial({color:'#292f2a',roughness:.9}),cat=type==='cat';root.name=cat?'Farm cat':'Farm dog';
 function ellipsoid(x,y,z,sx,sy,sz,mat=fur,parent=root){const m=new T.Mesh(new T.SphereGeometry(1,12,8),mat);m.position.set(x,y,z);m.scale.set(sx,sy,sz);parent.add(m);return m;}
 ellipsoid(0,.6,0,.28,.33,.61);ellipsoid(0,.65,.33,.24,.35,.25);head.position.set(0,.93,.5);root.add(head);ellipsoid(0,0,0,.24,.23,.23,fur,head);ellipsoid(0,-.06,.24,.15,.12,cat?.13:.27,fur,head);ellipsoid(0,-.03,cat?.34:.48,.075,.06,.05,dark,head);
 for(const side of [-1,1]){ellipsoid(side*.14,.04,.18,.035,.04,.035,dark,head);const ear=new T.Mesh(new T.ConeGeometry(cat?.12:.13,cat?.27:.32,cat?4:8),fur);ear.position.set(side*.17,.22,cat?0:-.07);ear.rotation.z=side*(cat?-.15:.9);head.add(ear);for(const z of [-.4,.4]){const pivot=new T.Group();pivot.position.set(side*.19,.58,z);root.add(pivot);ellipsoid(0,-.23,0,.085,.26,.095,fur,pivot);ellipsoid(0,-.46,.04,.1,.065,.15,fur,pivot);legs.push(pivot);}}
 tail.position.set(0,.78,-.53);root.add(tail);const curve=new T.CatmullRomCurve3([new T.Vector3(),new T.Vector3(0,.18,-.25),new T.Vector3(0,cat?.65:.35,-.4)]),tailMesh=new T.Mesh(new T.TubeGeometry(curve,9,cat?.045:.075,6,false),fur);tail.add(tailMesh);if(cat)root.scale.setScalar(.64);
 return {root,legs,tail,head,update(dt,a,moved){const walking=moved>0;for(let i=0;i<legs.length;i++)legs[i].rotation.x=walking?Math.sin(a.phase*9+i%2*Math.PI+(i>1?Math.PI:0))*.55:a.mode==='rest'?.65:0;head.rotation.x=a.mode==='graze'?.65:a.mode==='look'?-.15:0;head.rotation.y=Math.sin(a.phase*.65)*.12;tail.rotation.z=Math.sin(a.phase*(cat?1.3:4))*(cat?.15:.35);root.position.y=.2+(a.mode==='rest'?-.15:Math.sin(a.phase*2)*.008);}};
}
